// Pre-generate the MYTH images at boot so the FIRST user hit is instant instead
// of 8-14s. Runs one image at a time so it never competes with a real user's
// request during boot.
//
// SPEED (2026-10-19): the generated bytes are now ALSO written to a durable
// cache on the Railway volume (/data/imagecache). So after the very first boot
// the images are already on disk and this task finishes in SECONDS instead of
// re-generating all 25 (~15-20 min of work that used to slow the whole bot down
// right after every redeploy). Set WARM_IMAGES=0 to switch it off entirely, or
// WARM_IMAGES_COUNT=<n> to warm only the first n.
const img = require('../lib/imagegen.js');
const myth = require('../plugins/myth.js');

const PROMPTS = {
  alchemist: 'an alchemist in a laboratory, glowing potions',
  alieninvasion: 'alien invasion over a city, sci-fi',
  astral: 'astral projection, soul floating in space',
  atlantis: 'the lost city of atlantis underwater',
  centaur: 'a centaur warrior in a forest',
  conjurer: 'a conjurer casting spells, magic circles',
  cyborg: 'a cyborg warrior, futuristic armor',
  diviner: 'a diviner reading the future, crystal ball',
  dragonfire: 'a dragon breathing fire over mountains',
  earthquake: 'a massive earthquake splitting the earth',
  enchanter: 'an enchanter weaving magic runes',
  fairy: 'a glowing fairy in an enchanted forest',
  gladiator: 'a gladiator in the roman arena',
  griffin: 'a majestic griffin, half eagle half lion',
  guru: 'a wise guru meditating on a mountain',
  hurricane: 'a giant hurricane seen from space',
  illusionist: 'an illusionist performing a grand trick',
  knight: 'a knight in shining armor',
  mayan: 'a mayan temple in the jungle',
  medium: 'spiritual medium contacting spirits, seance',
  mermaid: 'a mermaid in a coral reef',
  monk: 'a monk in a mountain monastery',
  mystic: 'a mystic with glowing aura, ancient temple',
  necromancer: 'a necromancer raising the dead',
  ninja: 'a ninja on a rooftop at night',
};

(async () => {
  if (String(process.env.WARM_IMAGES || '1') === '0') return;
  // Start a little after boot so it never competes with the initial connect.
  await new Promise((r) => setTimeout(r, 30000));

  const all = Object.keys(PROMPTS).filter((n) => myth.commands.includes(n));
  const cap = Math.max(0, parseInt(process.env.WARM_IMAGES_COUNT || String(all.length), 10) || all.length);
  const names = all.slice(0, cap);
  const promptOf = (n) => `${PROMPTS[n]}, highly detailed digital art, epic cinematic lighting, 4k`;
  const opts = { width: 1024, height: 1024, user: '__warm__' };

  // Skip anything already cached (memory OR the durable /data cache) so a
  // redeploy finishes warming almost instantly.
  const todo = names.filter((n) => !img.isCached(promptOf(n), opts));
  console.log(`[warm] ${names.length} myth images \u2014 ${names.length - todo.length} already cached, warming ${todo.length}`);
  let fails = 0;
  for (const n of todo) {
    try {
      await img.generateImage(promptOf(n), opts);
      console.log('[warm] ok', n);
      fails = 0;
    } catch (e) {
      // The free image tier rate-limits (402) in bursts. Don't grind through all
      // 25 (~30 min of failing calls); bail out after a few consecutive failures.
      fails++;
      console.log('[warm] skip', n, '\u2014', (e && e.message) || e);
      if (fails >= 4) { console.log('[warm] image service unavailable \u2014 stopping warm-up'); break; }
    }
    await new Promise((r) => setTimeout(r, 3000));
  }
  console.log('[warm] done');
})();
